// `npm run android:patch` — idempotently re-applies the app-level
// AndroidManifest.xml customization that `npx cap sync android` does NOT
// manage on its own. `android/` is gitignored (regenerated by `npx cap add
// android` / kept in sync by `npx cap sync android`) — see .gitignore. Plugin
// permissions (POST_NOTIFICATIONS, WAKE_LOCK, RECEIVE_BOOT_COMPLETED from
// @capacitor/local-notifications) merge in automatically via Gradle manifest
// merger; USE_EXACT_ALARM is an app-level choice this project makes and is
// not contributed by any plugin, so it must be (re-)inserted by hand.
//
// Safe to run any time: no-ops if the manifest already has the permission, or
// if android/ doesn't exist yet (run `npx cap add android` first). Spec 001
// FR-12 / plan/architecture.md §4a.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const MANIFEST = join(ROOT, "android/app/src/main/AndroidManifest.xml");

const PERMISSION_TAG =
  '<uses-permission android:name="android.permission.USE_EXACT_ALARM" />';

const COMMENT = `    <!-- Drip pre-end/at-empty alarms must still fire with the screen locked
         (Spec 001 FR-12, Owner-reported 2026-07-21 -- the in-app alarm alone
         fired 7 min late after screen-off). USE_EXACT_ALARM is auto-granted
         (no user prompt) for apps whose core function is alarms/reminders;
         this app is sideloaded, not Play-Store-distributed, so the Play
         policy restriction on this permission doesn't apply. Without it the
         @capacitor/local-notifications plugin still degrades gracefully to
         setAndAllowWhileIdle (approximate timing under Doze) rather than
         failing outright. POST_NOTIFICATIONS/RECEIVE_BOOT_COMPLETED/WAKE_LOCK
         are already merged in automatically from the plugin's own manifest. -->
    ${PERMISSION_TAG}`;

if (!existsSync(MANIFEST)) {
  console.log(
    "android:patch — android/ not found yet; run `npx cap add android` first, then re-run this. Skipping.",
  );
  process.exit(0);
}

const xml = readFileSync(MANIFEST, "utf8");

if (xml.includes(PERMISSION_TAG)) {
  console.log("android:patch — USE_EXACT_ALARM already present, nothing to do.");
  process.exit(0);
}

if (!xml.includes("</manifest>")) {
  console.error("android:patch — could not find </manifest> in AndroidManifest.xml; aborting.");
  process.exit(1);
}

const patched = xml.replace("</manifest>", `\n${COMMENT}\n</manifest>`);
writeFileSync(MANIFEST, patched);
console.log("android:patch — inserted USE_EXACT_ALARM into AndroidManifest.xml.");
